options = read('/input/options')
goal = task['goal']
ids = []
for r in options:
    ids = ids + [r['id']]
candidates = []
for k in range(goal['min_count'], goal['max_count'] + 1):
    for combo in combinations(ids, k):
        selection = list(combo)
        if valid(selection):
            candidates = candidates + [selection]
ordered = []
for selection in candidates:
    records = []
    for ident in selection:
        for r in options:
            if r['id'] == ident:
                records = records + [r]
    records = sorted(records, key=lambda r: (r['rank'], r['id']))
    ordered = ordered + [[r['id'] for r in records]]
result = []
if len(ordered) > 0:
    result = ordered[0]

