artifact = read('/output/selection')
if artifact != None:
    if valid(artifact):
        result = artifact
    else:
        status('report')
else:
    if len(result) > 0 and valid(result):
        write('/output/selection', result)
        artifact = result
    else:
        artifact = []
if exists('/tmp/cache'):
    delete('/tmp/cache')
if len(artifact) > 0 and valid(artifact):
    delivery = receipt('report')
    if delivery == 'success':
        pass
    elif delivery == 'unknown':
        status('report')
    elif delivery == 'unattempted' or delivery == 'failure':
        send('report', 'team', artifact)
